    Check(bool(RegisterComponents()),"module component registration");Scene::World world;Scene::CommandHistory history;Check(bool(EnsureSettings(world,history)),"sky entities attach through commands");Settings extracted;Guid config,sun,moon;Check(bool(ReadSettings(world,extracted,config,sun,moon))&&config&&sun&&moon,"all sky components read from scene");Check(bool(history.Execute(world,std::make_unique<Scene::SetFieldCommand>(config,kTime,"time",4.f))),"existing command edits module field");Scene::FieldValue value;world.ReadField(config,kTime,"time",value);Check(std::get<float>(value)==4,"reflection reads edit");history.Undo(world);world.ReadField(config,kTime,"time",value);Check(std::get<float>(value)==12,"module field undo");
    auto path=std::filesystem::temp_directory_path()/"engine-f4-components.scene.json";Check(bool(Scene::SaveScene(world,path)),"module scene save");Scene::World loaded;Scene::CommandHistory loadHistory;std::vector<Guid> assets;Check(bool(Scene::LoadScene(loaded,loadHistory,path,assets)),"module scene load");Settings restored;Check(bool(ReadSettings(loaded,restored,config,sun,moon))&&restored.atmosphere.planetRadius==extracted.atmosphere.planetRadius&&restored.sun.light==extracted.sun.light,"module fields and light links roundtrip");std::filesystem::remove(path);
