    Check(bool(ApplyWeatherPreset(world,history,config,presets.front().parameters,0)),"visual script preset uses scene commands");sceneSystems.Update(world,0,extracted,state);Check(extracted.weather.current==presets.front().parameters,"script preset reaches exact values");
    std::mt19937 rng(73);std::uniform_real_distribution<double> uniform(-1,1);for(int i=0;i<2000;++i){double radius=6360000,altitude=i%7==0?1:i%7==1?100:i%7==2?10000:i%7==3?100000:i%7==4?1000000:40000000;glm::dvec3 origin{0,radius+altitude,0},direction=glm::normalize(glm::dvec3{uniform(rng),uniform(rng),uniform(rng)});auto exact=StableSphere(origin,direction,radius);auto approx=StableSphere(glm::vec3(origin),glm::vec3(direction),float(radius));if(exact.y>=0&&approx.y>=0){if(std::abs(exact.y-approx.y)>=std::max(32.0,std::abs(exact.y)*1e-4))std::cerr<<"Intersection sample "<<i<<" double "<<exact.y<<" float "<<approx.y<<" delta "<<std::abs(exact.y-approx.y)<<"\\n";Check(std::abs(exact.y-approx.y)<std::max(32.0,std::abs(exact.y)*1e-4),"planetary float/double intersection tolerance");}}float previous=SpaceBlend(50000);for(int i=1;i<=700;++i){float current=SpaceBlend(50000+i*100);Check(current>=previous&&current-previous<.003,"continuous orbital blend");previous=current;}Check(SpaceBlend(0)==0&&SpaceBlend(120000)==1,"ground/space blend endpoints");
